#!/usr/bin/env python3
"""protein/rfdiffusion_design — auto-generated run.py (archetype=structure_predict).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "structure_predict"
BRAIN = "protein"
SKILL = "rfdiffusion_design"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'rfdiffusion_design', 'sequence': '', 'model_path': '', 'plddt_mean': 0.0, 'ptm': 0.0, 'n_residues': 0, 'runtime_sec': 0.0, 'diagnostics': {'brain': 'protein', 'archetype': 'structure_predict'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """RFdiffusion de novo protein design。host_env=rfdiffusion(env 自带 run_inference.py)。
    输入:contigmap_contigs (RFdiffusion contig string) / num_designs / output_prefix
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    contigs = payload.get("contigmap_contigs") or payload.get("contigs")
    num = int(payload.get("num_designs", 4))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="rfdiff_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "RFdiffusion", "num_designs": num, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "sequence": "", "model_path": "",
                "plddt_mean": 0.0, "ptm": 0.0, "n_residues": 0, "runtime_sec": 0.0,
                "diagnostics": {**diagnostics, "dry": True}}
    if not contigs:
        return {"ok": False, "error": "需要 contigmap_contigs (RFdiffusion contig 字符串)", "diagnostics": diagnostics}
    cmd = ["run_inference.py",
           f"contigmap.contigs=[{contigs}]",
           f"inference.num_designs={num}",
           f"inference.output_prefix={_os.path.join(out_dir, 'design')}"]
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "RFdiffusion 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    import glob as _glob
    pdbs = sorted(_glob.glob(_os.path.join(out_dir, "design_*.pdb")))
    return {"ok": True, "skill_id": SKILL, "sequence": "",
            "model_path": pdbs[0] if pdbs else "",
            "plddt_mean": 0.0, "ptm": 0.0, "n_residues": 0,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "designs": pdbs}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
